export const KB = {"Q1":{"kb_id":"GSYG_01","core_orientation":"考察教师能否在幼儿自主生成的玩水游戏与规则、安全、场地适宜性之间作出专业判断：既不简单禁止，也不放任风险，而是顺应游戏兴趣并以适宜方式回应。","empirical_note":"第1题赋分中A/C为高价值路径，D靠前为主要风险。A体现延迟观察与后续讨论，C体现参与游戏与渐进转场，B体现规则协商，D提示可能用器械功能回归替代游戏理解。","paths":[{"option":"A","type":"实证高分锚点：延迟观察与后续讨论路径","suggest_pos":"优先/高价值锚点","reason":"第1题赋分中A首位平均得分最高；A体现教师尊重儿童正在生成的自主游戏，不急于立刻干预，并将规则教育放到儿童兴趣稍退后的反思讨论中，符合长期规则内化思路。","not_denying":"不是说教师永远不管，也不是放任风险；A的高价值依赖于“待兴趣减弱后再讨论”的后续专业行为。","evidence":["E1","E2","E3","E5"],"rel_bias":"A末位是重要风险；A首位需访谈确认不是放任。","rel_trigger":"A首位可触发T4高水平确认；A末位触发T2。"},{"option":"C","type":"实证高分锚点：参与游戏与渐进转场路径","suggest_pos":"优先/高价值锚点","reason":"C在最高分排序中与A共同出现，体现教师进入儿童游戏、保护兴趣，并以渐进方式把玩水从不适宜器械旁转到适宜空间。","not_denying":"不是说教师必须马上参与或控制游戏；若参与后过快主导转场，也需访谈确认儿童主体性。","evidence":["E1","E3","E4","E7"],"rel_bias":"C靠前通常为正向证据；C靠后可能提示支架不足。","rel_trigger":"C首位或靠前触发T5高水平确认。"},{"option":"B","type":"协调路径：肯定发现与规则协商路径","suggest_pos":"中高/协调路径","reason":"B体现肯定儿童发现和显性讨论场地适宜性，具有文化适宜的规则协商价值。","not_denying":"不是说B低价值；但如果过快提出换地方，可能仍偏成人安排，未充分保留游戏过程。","evidence":["E3","E6"],"rel_bias":"B首位或B压过A/C需访谈确认是否急于解决问题。","rel_trigger":"B首位或A/C靠后触发T3。"},{"option":"D","type":"风险路径：器械功能回归与注意转移路径","suggest_pos":"较低/不宜靠前","reason":"D首位平均得分极低，且最高分排序均将D放在末位；它强调器械原有功能和注意转移，容易忽视儿童玩水兴趣、材料再利用和长期规则建构。","not_denying":"不是说篮球架功能和运动价值不重要；问题在于以功能回归替代对当前游戏兴趣的理解与支持。","evidence":["E1","E2","E4","E7"],"rel_bias":"D首位或D靠前是核心风险。","rel_trigger":"D首位/靠前触发T1；D末位可作为高水平确认线索。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"不把“当场停止玩水”作为唯一目标，而重视儿童通过具体体验逐步理解适宜场地、安全边界和公共器械规则。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"篮球架是幼儿园公共器械，文化适宜的处理应兼顾儿童主体性、公共空间规则、安全责任和集体生活秩序。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"器械功能单一/注意转移优先","signal":"D排首位；D明显靠前；或D不在末位且A/C被压低。","why":"D把篮球架固定理解为打篮球工具，并通过召唤打篮球转移儿童注意，容易忽视当前玩水游戏价值。","problem":"教师可能把儿童自发改变材料用途视为偏离目标，需要立即拉回原功能。","check":"需核查教师是否能在保持器械规则的同时承认儿童玩水兴趣。","missing":["E1","E2","E4","E7"],"trigger":"T1","script":["Q1","Q2","Q3"]},{"code":"P2","name":"低估延迟观察与长期教育效果","signal":"A排末位；或A明显排在B/D之后。","why":"第1题赋分中A首位最高、A末位最低之一，说明低估A可能意味着忽视儿童体验和后续讨论价值。","problem":"教师可能认为教师必须立刻介入，未意识到规则教育可以在体验后通过讨论形成。","check":"需核查教师是否把A理解为放任，还是能理解其后续讨论价值。","missing":["E2","E5"],"trigger":"T2","script":["Q1","Q2","Q3"]},{"code":"P3","name":"即时规则解决过强","signal":"B排首位且A/C靠后；或B/D前置、A/C后置。","why":"B有规则协商价值，但若过早提议换地方，可能仍以成人判断替代儿童体验。","problem":"教师可能重视秩序与适宜性，但对游戏过程保留不足。","check":"若教师能让儿童参与判断并继续游戏，则风险降低。","missing":["E1","E2","E5","E6"],"trigger":"T3","script":["Q1","Q2","Q3"]},{"code":"P4","name":"参与式支架不足","signal":"C排末位；或C明显靠后且D/B靠前。","why":"C体现教师以游戏方式介入和渐进转场，低估C可能导致支持方式过于外在。","problem":"教师可能把参与儿童游戏视为不必要，或只把问题看成规则管理。","check":"需核查教师是否有其他保护游戏并转场的策略。","missing":["E4","E7"],"trigger":"T5","script":["Q2","Q3"]},{"code":"P5","name":"放任式尊重风险","signal":"A排首位但访谈中无法说明何时、如何讨论适宜性，也不考虑安全和公共规则。","why":"A首位是高分锚点，但其价值依赖“后续讨论”和安全判断；不能把A理解为完全不管。","problem":"教师可能把尊重自主游戏误解为不介入、不规则、不引导。","check":"此项不能仅由排序判断，必须结合访谈回答。","missing":["E3","E5","E6","E7"],"trigger":"T4","script":["Q2","Q3"]},{"code":"P6","name":"文化规则压倒儿童游戏","signal":"D或B靠前，访谈中只讲器械用途、园所秩序、不能弄湿，不承认儿童游戏兴趣。","why":"文化适宜性要求维护公共规则，但不等于用规则压制儿童生成性游戏。","problem":"教师可能把集体规则理解为服从性管理，而不是共建规则。","check":"需核查教师是否能用文化上可接受、儿童能理解的方式处理公共规则。","missing":["E1","E2","E6"],"trigger":"T1/T3","script":["Q2"]},{"code":"P7","name":"A/C高水平确认，不作为偏误","signal":"A或C排首位，D排末位；A/C前两位。","why":"A/C靠前符合实证高分逻辑，访谈用于确认教师是否能把尊重游戏、渐进转场和长期规则形成讲具体。","problem":"可能是高水平，也可能只是理念化表达。","check":"若教师能给出具体后续讨论或转场策略，应作为高水平证据。","missing":["E3","E5","E6"],"trigger":"T4/T5/T6","script":["Q2","Q3"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"D 排首位或进入前二","target":"D首位平均得分极低，且最高分排序均将D放在末位；它强调器械原有功能和注意转移，容易忽视儿童玩水兴趣、材料再利用和长期规则建构。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_A","prio":3,"result_cond":"A 排末位","target":"第1题赋分中A首位平均得分最高；A体现教师尊重儿童正在生成的自主游戏，不急于立刻干预，并将规则教育放到儿童兴趣稍退后的反思讨论中，符合长期规则内化思路。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_C","prio":3,"result_cond":"C 排末位","target":"C在最高分排序中与A共同出现，体现教师进入儿童游戏、保护兴趣，并以渐进方式把玩水从不适宜器械旁转到适宜空间。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(A/C)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"不把“当场停止玩水”作为唯一目标，而重视儿童通过具体体验逐步理解适宜场地、安全边界和公共器械规则。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"篮球架是幼儿园公共器械，文化适宜的处理应兼顾儿童主体性、公共空间规则、安全责任和集体生活秩序。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能先看见儿童对水、粉刷、接水和器械再利用的兴趣，再判断安全与场地边界，并通过参与、协商或后续讨论形成可持续规则。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"只强调篮球架原有功能或立即把孩子转回打篮球，忽视儿童正在生成的游戏兴趣与经验。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q2":{"kb_id":"GSYG_02","core_orientation":"考察教师能否透过“我不会、帮帮我”的表面求助，判断幼儿真实需要，并以小目标、提问或材料支架支持其自主尝试，而不是直接代做或过度示范。","empirical_note":"第2题赋分强调A首位、C靠前和B末位的价值。A支持自主性和自我效能，C体现观察诊断与适时反馈，D可作为小目标支架，B直接示范在本题中是主要风险路径。","paths":[{"option":"A","type":"实证首位锚点：自主性与自我效能支持路径","suggest_pos":"优先/高价值首位锚点","reason":"第2题赋分中A排首位平均得分最高，最高分ACDB也以A开头。A能接住小明已有能力，支持其自我效能和继续尝试，不急于替代。","not_denying":"不是说教师完全不帮助；A之后仍需观察反馈和必要小目标支架。","evidence":["E2","E7"],"rel_bias":"A末位或明显靠后提示可能低估自主性支持。","rel_trigger":"A末位触发T3；A首位用于高水平确认T5。"},{"option":"C","type":"观察诊断锚点：在旁观察与适时反馈路径","suggest_pos":"高价值诊断锚点","reason":"C体现观察诊断和适时反馈，能判断小明到底卡在哪里；A/C前两位平均分最高，说明A与C共同构成本题高价值路径。","not_denying":"不是说只观察不介入；观察后的反馈应短、准、可操作。","evidence":["E1","E3"],"rel_bias":"C明显靠后提示可能忽视真实需要诊断。","rel_trigger":"C靠后触发T2；C首位或A/C前两位可触发T5/T6。"},{"option":"D","type":"小目标支架路径","suggest_pos":"中高价值支架路径","reason":"D能把“我不会”转化为可完成的小步骤，符合中班幼儿需要具体目标的特点；但若过度指导目标，可能偏成人主导。","not_denying":"不是否定小目标支架；D应建立在观察和自主性支持基础上。","evidence":["E4","E6"],"rel_bias":"D靠前通常可理解，但若A/C被压低，需核查是否成人主导。","rel_trigger":"D首位触发T4确认支架强度。"},{"option":"B","type":"直接示范路径","suggest_pos":"较低/不宜靠前","reason":"B看似能快速解决问题，但在本题中风险是过早把求助解释为技能不会，并使幼儿转为照着教师做；第2题赋分中B首位平均最低，B末位平均最高。","not_denying":"不是说任何示范都不能用；在安全、技能明显缺失或多次尝试失败时，局部示范可以作为后位策略。","evidence":["E5","E7"],"rel_bias":"B首位或B靠前提示过度示范/即时解决取向。","rel_trigger":"B首位或B靠前触发T1。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"中班儿童需要在成人适度支持中积累“我能试一试”的经验；教育效果不只看本次是否搭好，更看长期自主性和坚持性。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"在集体活动中，教师既要回应儿童求助，也要保护其自尊和自主，不把“帮忙”变成公开能力比较或成人包办。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"直接示范优先/过度支架","signal":"B排首位；或B明显靠前，尤其B在A/C之前。","why":"第2题赋分中B首位平均最低，B末位平均最高；本题小明已有搭建能力，先示范可能过强。","problem":"教师可能把求助直接等同于技能不会，重短期解决、轻自主尝试。","check":"需核查教师是否会根据观察决定是否示范，以及示范是否局部、可退出。","missing":["E1","E2","E5","E7"],"trigger":"T1","script":["Q1","Q2","Q3"]},{"code":"P2","name":"忽视观察诊断","signal":"C靠后或C排末位；尤其教师最终B/A/D靠前但C靠后。","why":"题干显示语言与行为不一致，需要观察判断真实需要；若忽视C，可能凭表面求助回应。","problem":"教师可能没有先看儿童已会什么、卡在哪里。","check":"若教师能在访谈中具体说明观察线索，C靠后风险可降低。","missing":["E1","E3"],"trigger":"T2","script":["Q1","Q2"]},{"code":"P3","name":"低估自主性支持","signal":"A排末位或明显靠后。","why":"A是实证首位锚点；低估A可能说明教师没有把自信、坚持和自主性作为核心目标。","problem":"教师可能认为帮助就是给方法，而不是支持儿童自己继续尝试。","check":"需核查教师是否会先接住求助和肯定已有努力。","missing":["E2","E7"],"trigger":"T3","script":["Q2"]},{"code":"P4","name":"小目标支架成人主导化","signal":"D排首位且A/C被压低；或D靠前但理由强调教师指导目标。","why":"D有价值，但若先由教师设定目标，可能削弱儿童自主计划。","problem":"教师可能把小目标变成教师安排任务，而非与幼儿共同梳理下一步。","check":"若教师能说明先观察、先回顾幼儿已完成部分，再共同确定目标，则风险降低。","missing":["E3","E4","E6"],"trigger":"T4","script":["Q2"]},{"code":"P5","name":"空泛鼓励","signal":"A排首位但访谈中只能说“鼓励他”“表扬他”，无观察反馈和具体支架。","why":"A本身是高价值锚点，但高水平A必须连接C/D，否则可能只是不接管。","problem":"教师可能有自主性理念，但缺少可操作支架。","check":"排序不能直接判定，必须访谈确认。","missing":["E3","E4"],"trigger":"T5","script":["Q2","Q3"]},{"code":"P6","name":"短期作品完成取向","signal":"B/D靠前，理由集中在让房子尽快搭好。","why":"教育策略不应只看立刻完成作品，还要看儿童长期的坚持、自我效能和有效求助。","problem":"教师可能把建构结果看得重于学习过程。","check":"需核查教师是否关注长期效果。","missing":["E2","E5","E7"],"trigger":"T1/T4/T6","script":["Q3"]},{"code":"P7","name":"高水平A/C确认，不作为偏误","signal":"A/C前两位，尤其ACDB或ACBD。","why":"A/C组合与实证赋分高度协调，通常提示教师既支持自主又重视观察诊断。","problem":"仍需确认是否有具体语言、小目标支架和长期视角。","check":"若回答具体，可作为高水平证据。","missing":["E4","E6","E7"],"trigger":"T5/T6","script":["Q2","Q3"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"B 排首位或进入前二","target":"B看似能快速解决问题，但在本题中风险是过早把求助解释为技能不会，并使幼儿转为照着教师做；第2题赋分中B首位平均最低，B末位平均最高。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_A","prio":3,"result_cond":"A 排末位","target":"第2题赋分中A排首位平均得分最高，最高分ACDB也以A开头。A能接住小明已有能力，支持其自我效能和继续尝试，不急于替代。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_C","prio":3,"result_cond":"C 排末位","target":"C体现观察诊断和适时反馈，能判断小明到底卡在哪里；A/C前两位平均分最高，说明A与C共同构成本题高价值路径。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(A/C)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"中班儿童需要在成人适度支持中积累“我能试一试”的经验；教育效果不只看本次是否搭好，更看长期自主性和坚持性。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"在集体活动中，教师既要回应儿童求助，也要保护其自尊和自主，不把“帮忙”变成公开能力比较或成人包办。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能先观察小明实际搭建水平和求助原因，在接住情绪的同时避免替代完成，并用具体反馈或小目标支持其继续尝试。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"把频繁求助直接等同于不会，马上示范或替儿童解决，导致支架强度过高、削弱自主问题解决经验。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q3":{"kb_id":"GSYG_03","core_orientation":"考察教师能否持续观察幼儿频繁转换区域背后的原因，识别其是否真正投入、有无游戏目标或材料困难，再决定是否需要陪伴、任务支架或环境调整。","empirical_note":"第3题赋分中B首位具有重要价值，A/D靠前也可解释为具体任务和陪伴支架；C具有观察诊断价值，但不宜孤立作为第一现场策略。","paths":[{"option":"B","type":"实证高分锚点：规则稳定与班级文化路径","suggest_pos":"优先/高价值锚点","reason":"第3题赋分中B首位平均得分最高，B末位平均得分最低。小班区域活动需要前置规则、重复提醒和正向强化；这不是急于纠正，而是长期形成班级区域活动文化。","not_denying":"不是说只讲规则、不理解儿童；B必须以温和、具体、正向方式实施，避免点名批评。","evidence":["E2","E6","E7"],"rel_bias":"","rel_trigger":""},{"option":"A","type":"具体任务支架路径","suggest_pos":"高价值证据点","reason":"A将儿童已有动作转化为小班可理解的小目标，利用任务和分享期待支持持续参与；A靠前与高分排序相协调。","not_denying":"不是说用任务强行限制儿童；任务应轻量、具体、有游戏意味。","evidence":["E1","E3","E6"],"rel_bias":"","rel_trigger":""},{"option":"D","type":"陪伴支持与逐步退出路径","suggest_pos":"可高价值但需核查","reason":"D能以关系和共同游戏延长参与，符合小班幼儿需要；但若过度依赖教师陪伴，长期自主性和班级组织会受影响。","not_denying":"不是否定教师陪伴；关键在于陪伴后是否能逐步退出并转向儿童自主。","evidence":["E4","E6"],"rel_bias":"","rel_trigger":""},{"option":"C","type":"观察诊断路径","suggest_pos":"重要但不宜孤立首位","reason":"C有专业价值，但第3题赋分中C首位平均较低、C末位平均最高；说明本题更看重在已有明显行为线索下进行规则、任务或陪伴支持，而不是把观察分析孤立为首要策略。","not_denying":"不是否定观察诊断；观察应嵌入支持过程，服务于后续行动。","evidence":["E5"],"rel_bias":"","rel_trigger":""}],"evidence_points":[{"code":"E1","name":"指标定位证据：游戏中的观察","high":"回答能明确体现“游戏中的观察”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"小班幼儿区域习惯形成需要反复、温和、具体的支持，不宜只用成人标准要求长时间专注。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"区域活动是班级共同生活的一部分，规则提示和正向表扬应保护儿童安全感，避免公开比较和标签化。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"低估班级规则文化","signal":"B排末位，或B明显靠后且A/D/C靠前。","why":"","problem":"","check":"","missing":["E2","E6","E7"],"trigger":"","script":["Q1","Q-stop"]},{"code":"P2","name":"观察停留型","signal":"C首位，且后续A/B/D靠后。","why":"","problem":"","check":"","missing":["E5","E3","E4"],"trigger":"","script":["Q1","Q-stop"]},{"code":"P3","name":"任务控制型","signal":"A首位，但访谈中强调必须完成任务、必须分享成果。","why":"","problem":"","check":"","missing":["E1","E3","E6"],"trigger":"","script":["Q1","Q-stop"]},{"code":"P4","name":"成人陪伴依赖型","signal":"D首位，且B/A靠后。","why":"","problem":"","check":"","missing":["E4","E6","E7"],"trigger":"","script":["Q1","Q-stop"]},{"code":"P5","name":"即时效果导向","signal":"访谈中反复强调马上让儿童停下来、不要乱跑。","why":"","problem":"","check":"","missing":["E1","E6"],"trigger":"","script":["Q1","Q-stop"]},{"code":"P6","name":"文化适宜性不足","signal":"忽视班级规则、同伴榜样、集体活动文化，或用羞辱式表扬/比较。","why":"","problem":"","check":"","missing":["E2","E7"],"trigger":"","script":["Q1","Q-stop"]},{"code":"P7","name":"低估儿童探索价值","signal":"只强调规则或任务，完全不解释儿童为什么跑来跑去。","why":"","problem":"","check":"","missing":["E1","E5"],"trigger":"","script":["Q1","Q-stop"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"C 排首位或进入前二","target":"C有专业价值，但第3题赋分中C首位平均较低、C末位平均最高；说明本题更看重在已有明显行为线索下进行规则、任务或陪伴支持，而不是把观察分析孤立为首要策略。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_B","prio":3,"result_cond":"B 排末位","target":"第3题赋分中B首位平均得分最高，B末位平均得分最低。小班区域活动需要前置规则、重复提醒和正向强化；这不是急于纠正，而是长期形成班级区域活动文化。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_A","prio":3,"result_cond":"A 排末位","target":"A将儿童已有动作转化为小班可理解的小目标，利用任务和分享期待支持持续参与；A靠前与高分排序相协调。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(B/A)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“游戏中的观察”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"小班幼儿区域习惯形成需要反复、温和、具体的支持，不宜只用成人标准要求长时间专注。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"区域活动是班级共同生活的一部分，规则提示和正向表扬应保护儿童安全感，避免公开比较和标签化。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能通过规则稳定、具体任务、温和陪伴和后续正向反馈，帮助小班幼儿逐步形成区域活动习惯和持续参与经验。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"只停留在泛泛观察而缺少即时支持，或直接批评儿童不专心、不守规则。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：游戏中的观察","when":"该题得分偏低，或访谈显示无法围绕“游戏中的观察”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q4":{"kb_id":"GSYG_04","core_orientation":"考察教师能否理解幼儿个体兴趣与小组共同任务之间的关系，并以支持者、合作者的方式把个人发现转化为共同建构资源。","empirical_note":"第4题赋分突出B为高分锚点，即肯定创造性玩法并把长条板接入搭桥任务；C有共同计划价值，D有尊重自主价值，A的延后反思需要与当下支持协调。","paths":[{"option":"B","type":"实证高分锚点：兴趣整合共同任务路径","suggest_pos":"优先/高价值锚点","reason":"B直接把个人材料兴趣转化为共同建构资源，既保护儿童探索，又支持其回到小组任务；第4题赋分中B首位平均得分最高，BD开头的排序均为高分。","not_denying":"不是说必须立刻让睿睿完全停止个人玩法；而是通过开放问题让幼儿看见个人兴趣与共同任务可以连接。","evidence":["E1","E2","E4"],"rel_bias":"B靠后或B末位是重要风险；B首位属于实证高分锚点。","rel_trigger":"B靠后触发T4；B首位可用于高水平确认T5。"},{"option":"D","type":"自主尊重与长期观察锚点","suggest_pos":"有价值但不完整，不宜简单末位","reason":"D体现不急于打断儿童兴趣、尊重游戏自主和等待长期机会的意识；实证赋分不支持把D简单放在末位。","not_denying":"不是说教师可以完全放任；D如果缺少当下连接小组任务和后续支持，仍然不完整。","evidence":["E3","E5"],"rel_bias":"D末位可能提示教师过度急于控制；D首位也可能提示当下支架不足。","rel_trigger":"D末位触发T3；D首位触发T6确认是否会后续支持。"},{"option":"C","type":"计划责任与任务回顾路径","suggest_pos":"中高价值但需防止过硬","reason":"C体现大班共同计划、任务坚持和合作责任意识；在部分高分排序中C可处于首位，但若只强调先完成任务，会压缩材料创新和计划调整。","not_denying":"不是否定计划意识；而是强调计划也可以在幼儿发现新材料后通过协商调整。","evidence":["E3","E6"],"rel_bias":"C首位需追问是否过度任务化；C靠前若能与D/B结合可解释为重视共同体责任。","rel_trigger":"C首位触发T2。"},{"option":"A","type":"延后反思路径","suggest_pos":"有长期价值但不宜首位","reason":"A尊重观察和后续分享的价值，但如果只等分享环节再处理，容易错过当下把长条板接入搭桥任务的机会，也可能让小组合作断裂持续存在。","not_denying":"不是否定观察和分享；而是观察应服务于当下或后续的有效支架，不能成为延迟支持的理由。","evidence":["E5","E2","E4"],"rel_bias":"A首位是延后处理风险；A末位在高分排序中较常见，说明其不宜作为优先路径。","rel_trigger":"A首位触发T1。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"大班儿童已有计划、合作和协商能力，教师支持不应只追求立刻归队，而应促进儿童学习把个人想法纳入共同游戏。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"中国幼儿园强调合作与共同任务，但文化适宜的合作不是服从计划，而是在共同目标中保留儿童创造性。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"延后处理替代当下支架","signal":"A排首位，尤其B靠后。","why":"A有观察和后续分享价值，但A首位可能说明教师错过当下整合材料兴趣和共同任务的机会。","problem":"教师可能习惯把问题留到分享环节，而不是在游戏现场提供低控制支架。","check":"需核查教师是否有当下观察—即时连接—后续反思的完整计划。","missing":["E2","E4"],"trigger":"T1","script":["Q1","Q2","Q3"]},{"code":"P2","name":"计划任务化/共同计划僵化","signal":"C排首位且B/D靠后。","why":"C体现计划责任，但若只强调先完成任务，可能压缩材料探索和计划协商。","problem":"教师可能把大班计划理解为必须完成的任务，而不是可协商调整的共同方案。","check":"若教师能说明如何邀请睿睿和同伴讨论长条板用途，风险降低。","missing":["E1","E2","E7"],"trigger":"T2","script":["Q1","Q2","Q3"]},{"code":"P3","name":"低估自主兴趣和长期支持","signal":"D排末位，尤其教师解释为“玩得开心也要马上拉回任务”。","why":"D末位在第4题实证赋分中并不支持；可能提示教师过度追求立刻回归任务，低估保护兴趣和长期效果。","problem":"教师可能偏向管理和任务完成，忽视儿童自主探索。","check":"需核查教师是否并非否定自主，而是认为D缺少支架。","missing":["E3","E5","E6"],"trigger":"T3","script":["Q2"]},{"code":"P4","name":"低估兴趣整合路径","signal":"B排末位或明显靠后。","why":"B是实证高分锚点，低估B说明教师可能没有抓住本题关键。","problem":"教师可能把个人玩法和共同任务看作对立，而不能把长条板转化为桥的资源。","check":"需核查教师是否能在追问后生成整合策略。","missing":["E1","E2","E4"],"trigger":"T4","script":["Q2","Q3"]},{"code":"P5","name":"只尊重个体而忽视共同任务","signal":"D排首位，且访谈中不能说明如何回到小组搭桥。","why":"D有尊重自主价值，但如果停留在“他玩得开心就不介入”，可能忽视大班共同计划和同伴合作。","problem":"教师可能把尊重儿童理解为不需要支架。","check":"此项不能仅由D首位定论，必须通过访谈确认。","missing":["E2","E3","E4"],"trigger":"T6","script":["Q2","Q3"]},{"code":"P6","name":"只重计划责任而忽视儿童材料创新","signal":"C/A靠前，B明显靠后。","why":"共同计划很重要，但儿童的新材料发现也可能成为小组建构资源。","problem":"教师可能习惯以规则、任务和秩序处理游戏变化。","check":"若教师能说明计划可调整和同伴协商，风险降低。","missing":["E1","E2","E7"],"trigger":"T2/T4","script":["Q2"]},{"code":"P7","name":"B首高水平确认，不作为偏误","signal":"B排首位，D/C/A中间排序有犹豫。","why":"B首位符合实证高分逻辑，访谈只需确认教师是否真正采用开放、协商式支架。","problem":"教师可能较快想到桥面整合，但不一定关注同伴协商。","check":"若教师能说明会让睿睿和小组共同决定长条板用途，应作为高水平证据。","missing":["E3","E6","E7"],"trigger":"T5","script":["Q2","Q3"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"A 排首位或进入前二","target":"A尊重观察和后续分享的价值，但如果只等分享环节再处理，容易错过当下把长条板接入搭桥任务的机会，也可能让小组合作断裂持续存在。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_B","prio":3,"result_cond":"B 排末位","target":"B直接把个人材料兴趣转化为共同建构资源，既保护儿童探索，又支持其回到小组任务；第4题赋分中B首位平均得分最高，BD开头的排序均为高分。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"D体现不急于打断儿童兴趣、尊重游戏自主和等待长期机会的意识；实证赋分不支持把D简单放在末位。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(B/D)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"大班儿童已有计划、合作和协商能力，教师支持不应只追求立刻归队，而应促进儿童学习把个人想法纳入共同游戏。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"中国幼儿园强调合作与共同任务，但文化适宜的合作不是服从计划，而是在共同目标中保留儿童创造性。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能接住睿睿对长条板的兴趣，并通过开放提问、材料连接和同伴协商，把个人玩法转化为小组建构的新可能。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"只要求其回到原计划，或完全放任个人玩法而不支持小组共同任务。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q5":{"kb_id":"GSYG_05","core_orientation":"考察教师能否区分幼儿游戏中的角色体验、情节表达与成人现实价值判断，先理解游戏意义，再以发展适宜的方式进行安全和价值澄清。","empirical_note":"第5题实证赋分突出B为最高价值锚点，即先澄清孩子开心来源；D具有开放倾听价值；A可作为直观安全说明，但若过早会脱离游戏；C“值不值得开心”较抽象且带评判性，是主要风险路径。","paths":[{"option":"B","type":"实证高分锚点：澄清游戏意义路径","suggest_pos":"优先/高价值锚点","reason":"B直接澄清儿童“开心”的对象，能把“着火开心”的表层表达转化为“救火成功、娃娃得救、消防员完成任务”的积极经验；第5题赋分中BADC为最高分，B首位平均得分最高。","not_denying":"不是说B之后不需要倾听；B首位仍需访谈确认教师是否会保留儿童叙事空间。","evidence":["E1","E3","E4"],"rel_bias":"B末位或明显靠后是重要风险；B首位属于实证高分锚点，作为高水平确认线索。","rel_trigger":"B末位触发T4；B首位可用于高水平确认T5。"},{"option":"D","type":"儿童视角锚点：开放倾听路径","suggest_pos":"高价值证据点","reason":"D体现开放倾听、儿童视角和游戏叙事理解，是判断教师是否理解儿童游戏体验的重要证据。","not_denying":"不是说只倾听、不做价值澄清；D首位后仍需走向真实火灾危险和积极价值澄清。","evidence":["E2","E5"],"rel_bias":"D靠后提示可能低估儿童叙事，但不单凭D末位直接判重度偏误。","rel_trigger":"D明显靠后触发T3；D首位可触发T6确认完整链条。"},{"option":"A","type":"直接安全说明路径","suggest_pos":"可理解但不宜抢先","reason":"A的安全信息具体、直观，中班幼儿较易理解；但若排在最前且替代对游戏体验的理解，容易形成说教优先。","not_denying":"不是否定安全教育；若A出现在B之后，可能是“澄清后补充安全价值”，不宜简单判低。","evidence":["E3","E1","E2"],"rel_bias":"A首位且B/D靠后提示安全说教优先；A不作为固定末位要求。","rel_trigger":"A首位或A压过B/D触发T1。"},{"option":"C","type":"抽象价值判断路径","suggest_pos":"较低/不宜首位","reason":"C有价值教育意图，但“值不值得开心”对中班幼儿较抽象，容易把游戏情绪转化为成人价值评判，发展适宜性不足；这可解释C首位得分偏低，甚至低于部分A首位排序。","not_denying":"不是说不能进行价值教育；而是价值教育要先具体化、情境化、非评判化。","evidence":["E4","E1","E2"],"rel_bias":"C首位是发展适宜性与规范纠偏风险；C末位不宜被解释为严重低估价值澄清。","rel_trigger":"C首位触发T2。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏特点的理解","high":"回答能明确体现“对游戏特点的理解”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"中班幼儿理解价值和安全需要依托具体经验和游戏叙事，不宜过早使用抽象道德判断。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"安全教育是幼儿园重要责任，但文化适宜的安全教育应先理解儿童游戏表达，再进行具体、温和、可理解的价值澄清。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"安全说教优先","signal":"A排首位且B/D被压低；或A/C前置、B/D后置。","why":"A有直观安全说明价值，但若抢在澄清开心来源之前，可能把游戏分享改造成安全说教。","problem":"教师可能把儿童游戏表达直接视为价值错误或安全教育契机。","check":"需核查教师能否在追问后先判断儿童开心来源，再说明真实火灾危险。","missing":["E1","E2","E3","E5"],"trigger":"T1","script":["Q1","Q2","Q3"]},{"code":"P2","name":"抽象价值判断过早/发展适宜性不足","signal":"C排首位。","why":"C有价值教育意识，但“值不值得开心”对中班幼儿较抽象，容易形成成人化价值评判。","problem":"教师可能重视价值正确性，但忽视幼儿理解水平和游戏情绪表达特点。","check":"需核查教师能否把价值判断改为具体、开放、非评判的澄清问题。","missing":["E1","E4","E5"],"trigger":"T2","script":["Q1","Q2","Q3"]},{"code":"P3","name":"低估儿童游戏叙事","signal":"D明显靠后，且访谈中不能说明如何理解儿童游戏过程。","why":"D体现开放倾听和儿童视角；但D靠后不单独构成严重偏误，应结合B位置和访谈回答判断。","problem":"教师可能认为倾听儿童讲述“不够教育”，更偏好立即讲解或纠正。","check":"若教师能通过B澄清开心来源并保留儿童表达空间，则D靠后风险可降低。","missing":["E2","E5"],"trigger":"T3","script":["Q1","Q2"]},{"code":"P4","name":"低估开心来源澄清","signal":"B排末位；或B明显排在A/C之后。","why":"B是第5题实证高分锚点，低估B说明教师可能没有抓住本题核心。","problem":"教师可能不知道如何把“着火开心”转化为“救火成功、保护他人”等积极经验。","check":"需核查教师是否会用开放问题确认儿童开心对象。","missing":["E1","E3","E4"],"trigger":"T4","script":["Q2","Q3"]},{"code":"P5","name":"成人常规价值压倒游戏理解","signal":"A/C排前两位，B/D排后两位。","why":"A/C代表较强成人规范介入，B/D代表澄清与理解；前者过度前置会压缩儿童游戏经验。","problem":"教师可能习惯从安全、规范、管理出发，而不是从儿童游戏经验出发。","check":"需核查教师是否能在实际中接住儿童分享，而不是中断或纠错。","missing":["E1","E2","E5","E7"],"trigger":"T1/T2/T3","script":["Q1","Q2"]},{"code":"P6","name":"只看游戏不看价值澄清","signal":"D靠前但访谈中只说尊重儿童游戏，无法说明真实火灾危险。","why":"D是高价值证据点，但不代表完整能力；完整能力还包括游戏与现实区分和价值澄清。","problem":"教师可能误把尊重游戏理解为不需要安全与价值澄清。","check":"此项不能仅由排序判断，必须结合访谈回答。","missing":["E3","E4","E7"],"trigger":"T6","script":["Q2","Q3"]},{"code":"P7","name":"B首高水平确认，不作为偏误","signal":"B排首位，D第二或靠后。","why":"B首位符合实证高分逻辑，访谈只需确认教师是否保留儿童叙事空间。","problem":"教师可能较快进入澄清开心来源，但不一定有问题。","check":"若教师能让儿童继续讲述并后续澄清真实危险，应作为高水平证据。","missing":["E2","E5"],"trigger":"T5","script":["Q2"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"C 排首位或进入前二","target":"C有价值教育意图，但“值不值得开心”对中班幼儿较抽象，容易把游戏情绪转化为成人价值评判，发展适宜性不足；这可解释C首位得分偏低，甚至低于部分A首位排序。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_B","prio":3,"result_cond":"B 排末位","target":"B直接澄清儿童“开心”的对象，能把“着火开心”的表层表达转化为“救火成功、娃娃得救、消防员完成任务”的积极经验；第5题赋分中BADC为最高分，B首位平均得分最高。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"D体现开放倾听、儿童视角和游戏叙事理解，是判断教师是否理解儿童游戏体验的重要证据。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(B/D)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏特点的理解”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"中班幼儿理解价值和安全需要依托具体经验和游戏叙事，不宜过早使用抽象道德判断。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"安全教育是幼儿园重要责任，但文化适宜的安全教育应先理解儿童游戏表达，再进行具体、温和、可理解的价值澄清。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能先询问孩子开心的是救火成功、娃娃得救还是着火本身，再在理解游戏叙事的基础上进行具体、发展适宜的安全澄清。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"直接评判“着火不值得开心”或马上进行抽象价值纠偏，忽视儿童是在游戏框架中表达角色体验和任务成功。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏特点的理解","when":"该题得分偏低，或访谈显示无法围绕“对游戏特点的理解”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q6":{"kb_id":"GSYG_06","core_orientation":"考察教师能否从幼儿发展和学习经验角度分析任务材料的层次，动态调整材料呈现方式，并通过适度挑战支持幼儿在游戏中继续发展。","empirical_note":"第6题赋分中D和C为高价值路径，D体现个别回顾与适度挑战支架，C体现环境提示与挑战文化；A控制性分配任务卡为主要风险路径，B有自主尊重但可能放任低挑战重复。","paths":[{"option":"D","type":"实证高分锚点一：D","suggest_pos":"","reason":"","not_denying":"","evidence":["E1","E2","E3","E5"],"rel_bias":"","rel_trigger":"T5/T6"},{"option":"C","type":"实证高分锚点二：C","suggest_pos":"","reason":"","not_denying":"","evidence":["E2","E4","E5","E6"],"rel_bias":"","rel_trigger":"T4/T6"},{"option":"B","type":"自主尊重中间路径：B","suggest_pos":"","reason":"","not_denying":"","evidence":["E2","E5","E7"],"rel_bias":"","rel_trigger":"T2/T6"},{"option":"A","type":"控制性分配风险路径：A","suggest_pos":"","reason":"","not_denying":"","evidence":["E2","E4","E6","E7"],"rel_bias":"","rel_trigger":"T1/T3"}],"evidence_points":[{"code":"E1","name":"指标定位证据：游戏环境创设","high":"回答能明确体现“游戏环境创设”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"大班儿童可以逐步学习自我评价和选择挑战；支持目标不是当场换高难度，而是形成温和、持续、可选择的挑战意识。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"材料分层不应公开化能力标签，应保护儿童面子和选择权，营造“可以挑战、可以再试”的班级文化。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"教师控制性分配优先","signal":"A排首位；A靠前；A不在末位。","why":"A首实证得分最低，说明教师直接按能力发卡与本题高分逻辑不协调。","problem":"教师可能重视效率和匹配，却忽视儿童自主选择、自我评价和挑战文化。","check":"需核查其是否会公开分层、是否给儿童选择与调整机会。","missing":["E2","E6","E7"],"trigger":"T1/T3","script":["Q1","Q2","Q3"]},{"code":"P2","name":"尊重自主被动化/放任化","signal":"B排首位且D/C靠后。","why":"B有尊重价值，但若成为首位且缺少支架，可能让儿童长期停留在低挑战重复中。","problem":"教师可能把“不干预”理解为尊重，缺少长期学习品质意识。","check":"需核查教师何时会介入、怎样介入而不破坏自主。","missing":["E1","E2","E5"],"trigger":"T2","script":["Q1","Q2","Q3"]},{"code":"P3","name":"能力标签化风险","signal":"A首且教师解释中强调“按能力发卡”“能力低就给低星”。","why":"可能形成公开比较、固定标签或面子压力，不利于文化适宜性。","problem":"教师可能过度相信成人诊断与管理效率。","check":"若教师说明是私下、动态、可选择的建议，风险可降低。","missing":["E6","E7"],"trigger":"T3","script":["Q2"]},{"code":"P4","name":"低估环境支架和挑战文化","signal":"C排末位或C明显靠后。","why":"C体现通过任务卡呈现方式支持儿童自主挑战，是重要中高水平证据。","problem":"教师可能只看到个别儿童行为，而忽视材料系统和班级挑战氛围。","check":"需核查其是否会通过环境提示减少教师控制。","missing":["E4","E5","E6"],"trigger":"T4","script":["Q2"]},{"code":"P5","name":"低估个别化适度挑战支架","signal":"D排末位或D明显靠后。","why":"D是第6题最强实证高分锚点，D末位提示教师可能没有抓住本题核心。","problem":"教师可能不会基于儿童已完成经验进行回顾、比较和邀请挑战。","check":"需核查教师是否知道如何把浩浩的一星成功经验转向稍高挑战。","missing":["E1","E3","E5"],"trigger":"T5","script":["Q2"]},{"code":"P6","name":"只看即时选择，不看长期效果","signal":"B靠前且回答中只说孩子开心、完成任务就好。","why":"策略不必立竿见影，但长期效果不能被忽视。","problem":"教师可能把游戏自由理解为无需挑战成长。","check":"需核查其是否有后续观察和渐进支持计划。","missing":["E5"],"trigger":"T2/T6","script":["Q3"]},{"code":"P7","name":"D/C高水平确认","signal":"D或C首位，A末位。","why":"这通常符合实证高分逻辑，但仍需确认教师的具体实施是否发展适宜。","problem":"教师可能有正确方向，但语言和步骤未必具体。","check":"需确认其是否保留儿童选择权，避免把邀请做成命令。","missing":["E6"],"trigger":"T6","script":["Q2"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"A 排首位或进入前二","target":"确认教师是否高估了风险路径 A，能否看见儿童游戏兴趣与适宜支持。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"确认教师是否低估了高价值路径 D 的专业价值。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_C","prio":3,"result_cond":"C 排末位","target":"确认教师是否低估了高价值路径 C 的专业价值。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(D/C)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“游戏环境创设”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"大班儿童可以逐步学习自我评价和选择挑战；支持目标不是当场换高难度，而是形成温和、持续、可选择的挑战意识。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"材料分层不应公开化能力标签，应保护儿童面子和选择权，营造“可以挑战、可以再试”的班级文化。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能根据儿童已完成任务和当前经验，通过任务卡呈现、挑战提示、个别回顾和邀请式语言支持儿童选择稍有挑战的任务。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"按教师判断直接给不同能力儿童分发任务卡，或长期不介入儿童低挑战重复。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：游戏环境创设","when":"该题得分偏低，或访谈显示无法围绕“游戏环境创设”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q7":{"kb_id":"GSYG_07","core_orientation":"考察教师能否理解幼儿角色兴趣和审美经验，并把“艾莎公主”的游戏兴趣转化为符合年龄特点的运动参与，而不是简单要求儿童回到运动任务。","empirical_note":"第7题赋分突出C为实证高分锚点，即利用艾莎公主兴趣设计走、跑、跳活动；B简单提醒“现在是运动时间”是主要风险路径；A和D有价值，但需要转化为具体动作经验。","paths":[{"option":"C","type":"实证高分锚点：兴趣转化与身体活动融合路径","suggest_pos":"优先/高价值锚点","reason":"C把儿童已有角色兴趣直接转化为走、跑、跳等运动经验；第7题赋分中C首位平均得分最高，CADB、CDAB为最高分。","not_denying":"不是说教师必须立刻设计复杂活动；关键是用儿童能进入的情境把身体活动自然嵌入游戏。","evidence":["E1","E2","E4","E5"],"rel_bias":"C不靠前提示可能缺少兴趣转化能力；C首位用于高水平确认。","rel_trigger":"C首触发T5；C靠后触发T3。"},{"option":"A","type":"诊断与材料吸引路径","suggest_pos":"有价值但需转化","reason":"A体现了解原因和材料支持意识，较符合尊重儿童和环境支持原则；但若只停留在询问或材料投放，可能不能把当前艾莎游戏转成运动。","not_denying":"不是否定观察诊断和材料投放；A适合作为C之前或之后的辅助支架。","evidence":["E3","E5","E6"],"rel_bias":"A首位可为中等或较好路径，需访谈确认是否能具体转化。","rel_trigger":"A首触发T2；A靠前可作为支持性证据。"},{"option":"D","type":"兴趣认可与口头引导路径","suggest_pos":"中高价值辅助路径","reason":"D尊重儿童自主游戏和审美/角色兴趣，也尝试把鞋子经验引向运动；但主要依靠言语引导，动作情境和支架力度弱于C。","not_denying":"不是说D不好；D体现儿童视角，但需要进一步具体化为走、跑、跳等身体经验。","evidence":["E3","E4","E7"],"rel_bias":"D靠前通常不是偏误，访谈应确认是否会具体化。","rel_trigger":"D首触发T6；D靠前用于确认。"},{"option":"B","type":"时间规则与活动切换路径","suggest_pos":"主要风险路径/不宜优先","reason":"B维护活动时间边界，但把儿童兴趣推迟到自由游戏，容易中断小班儿童的角色兴趣，也没有把兴趣转化为运动参与；第7题赋分中B末位平均得分最高。","not_denying":"不是否定运动时间规则；而是规则应通过游戏化方式被儿童理解和接受。","evidence":["E1","E2","E3","E4"],"rel_bias":"B首位或B靠前是重要风险；B末位可作为较好判断。","rel_trigger":"B首触发T1；B末位可作为实证正向信号。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"小班儿童运动参与常常需要角色、情节和成人陪伴支持；不宜用成人式时间规则切断游戏兴趣。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"运动活动需要面向全体儿童，但文化适宜的组织不是整齐划一，而是用儿童喜欢的角色经验帮助其参与集体活动。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"规则时间优先、兴趣切断","signal":"B排首位；或B明显排在C/D之前。","why":"B维护时间规则，但本题赋分显示B首位风险较高、B末位平均得分最高。","problem":"教师可能把运动时间理解为必须中断角色游戏，而不是把角色游戏转化为运动。","check":"需核查教师是否能用游戏化方式落实运动目标，而不是只要求延后。","missing":["E1","E2","E3","E4","E7"],"trigger":"T1","script":["Q1","Q2","Q3"]},{"code":"P2","name":"材料吸引替代兴趣转化","signal":"A排首位但C靠后；或只强调提供材料。","why":"A有诊断和环境支持价值，但若缺少与艾莎情境的连接，可能不能推动当前儿童参与。","problem":"教师可能偏向外部材料吸引，而忽视儿童已有游戏内容本身就是支架资源。","check":"需核查教师能否基于艾莎兴趣设计动作情节。","missing":["E1","E5"],"trigger":"T2","script":["Q1","Q2","Q3"]},{"code":"P3","name":"低估兴趣转化策略","signal":"C排末位或明显靠后。","why":"C是本题实证高分锚点，低估C说明教师可能没有抓住兴趣转化的关键。","problem":"教师可能把运动和角色游戏割裂，认为只有进入固定体育项目才算运动。","check":"需核查教师是否能把走、跑、跳嵌入角色游戏。","missing":["E1","E2","E4","E5"],"trigger":"T3","script":["Q2","Q3"]},{"code":"P4","name":"低估儿童自主游戏与文化经验","signal":"D末位且教师不能说明艾莎游戏的意义。","why":"D体现肯定儿童自主游戏和尊重流行文化/审美经验。","problem":"教师可能将公主游戏视为与运动无关或不适合户外运动。","check":"若C首位且能尊重儿童兴趣，D靠后风险可降低。","missing":["E3","E7"],"trigger":"T4","script":["Q2"]},{"code":"P5","name":"只认可兴趣但运动支架不足","signal":"D首位或D靠前，但回答中只有肯定儿童，没有具体动作设计。","why":"D有儿童视角价值，但本题最终要看是否能促进身体活动参与。","problem":"教师可能停留在尊重儿童，不知道如何继续推进运动目标。","check":"需核查是否能把“漂亮鞋子/魔法”转为动作任务。","missing":["E4","E5"],"trigger":"T6","script":["Q2","Q3"]},{"code":"P6","name":"即时合规取向过强","signal":"B靠前、A靠前，C/D靠后。","why":"教师可能追求儿童马上回到运动项目，忽视运动兴趣和长期参与。","problem":"策略可能短期有效，但长期上降低儿童主动参与运动的意愿。","check":"需核查教师是否考虑长期运动兴趣与积极情绪体验。","missing":["E6","E7"],"trigger":"T1/T2","script":["Q1","Q3"]},{"code":"P7","name":"C首高水平确认，不作为偏误","signal":"C排首位，B靠后或末位。","why":"C首位符合实证高分逻辑；访谈只需确认策略是否真正具体、发展适宜、文化适宜。","problem":"教师可能有较好兴趣转化意识，但还需确认不是表面借用“艾莎”名义。","check":"若能说出具体动作情节、教师参与和后续延展，应作为高水平证据。","missing":["E3","E6","E7"],"trigger":"T5","script":["Q2","Q3"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"B 排首位或进入前二","target":"B维护活动时间边界，但把儿童兴趣推迟到自由游戏，容易中断小班儿童的角色兴趣，也没有把兴趣转化为运动参与；第7题赋分中B末位平均得分最高。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_C","prio":3,"result_cond":"C 排末位","target":"C把儿童已有角色兴趣直接转化为走、跑、跳等运动经验；第7题赋分中C首位平均得分最高，CADB、CDAB为最高分。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"D尊重儿童自主游戏和审美/角色兴趣，也尝试把鞋子经验引向运动；但主要依靠言语引导，动作情境和支架力度弱于C。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(C/D)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"小班儿童运动参与常常需要角色、情节和成人陪伴支持；不宜用成人式时间规则切断游戏兴趣。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"运动活动需要面向全体儿童，但文化适宜的组织不是整齐划一，而是用儿童喜欢的角色经验帮助其参与集体活动。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能承认孩子的艾莎角色兴趣，并设计“公主过冰桥、魔法跳跃、雪花跑”等小班可参与的身体游戏。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"只要求儿童把艾莎游戏留到自由游戏，或只用漂亮鞋子口头劝说，未把兴趣转化为动作活动。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q8":{"kb_id":"GSYG_08","core_orientation":"考察教师能否在幼儿探究兴趣减弱时，判断困难来源，选择适当介入时机，并通过材料、问题或示范支架恢复探索，而不是急于替幼儿完成。","empirical_note":"第8题赋分突出D为高分锚点，即投放辅助材料、重新激起探索兴趣并继续观察；B教师立即加入一起调竹片是主要风险路径；A短时可视化示范和C讨论共构有价值，但需与具体操作和兴趣重建结合。","paths":[{"option":"D","type":"实证高分锚点：材料扩展与兴趣重建路径","suggest_pos":"优先/高价值锚点","reason":"D抓住了题干中“兴趣减弱、有人离开”的关键信号。通过材料扩展和环境支架重建探索条件，符合中班幼儿通过操作经验学习的特点，也有利于长期探究兴趣。","not_denying":"不是说教师只投材料、不再支持；D之后仍需观察幼儿如何使用材料，并在必要时显化关键经验。","evidence":["E2","E3","E6"],"rel_bias":"D末位或明显靠后提示可能低估兴趣重建与材料支架。","rel_trigger":"D末位触发T1；D首位可用于高水平确认T5。"},{"option":"A","type":"可视化示范路径","suggest_pos":"高价值补充/中高价值","reason":"A能够把水流方向、坡度和入口关系具体化。对中班幼儿而言，短时、可观察、可复做的示范比抽象讨论更发展适宜。","not_denying":"不是鼓励教师包办；示范必须有限度，应让儿童观察、表达和再尝试。","evidence":["E1","E4"],"rel_bias":"A首位可能有成人主导风险，但若与D协调，属于可接受支架。","rel_trigger":"A首位或A靠前触发T2确认示范边界。"},{"option":"C","type":"讨论共构路径","suggest_pos":"有价值但需具体化","reason":"C重视同伴交流和方案共构，但在幼儿兴趣已下降、问题具有明显物理结构时，若先进行抽象讨论，可能不如材料操作和可视化支架适宜。","not_denying":"不是否定讨论；讨论需要建立在具体观察、材料尝试和问题证据上。","evidence":["E5","E6"],"rel_bias":"C首位需核查是否空泛讨论；C靠后不一定是偏误。","rel_trigger":"C首位触发T3。"},{"option":"B","type":"即时共调路径","suggest_pos":"风险路径/不宜优先","reason":"B看似贴近问题，但“加入并一起调整”容易变成教师即时修正和局部调对，弱化儿童通过材料、观察和试误形成经验；第8题赋分中B首位平均最低，B末位平均最高。","not_denying":"不是否定共同观察；真正高质量的共同观察应避免教师主导调好，应让儿童自己提出和尝试方案。","evidence":["E1","E2","E3","E6"],"rel_bias":"B首位或B明显靠前提示过度即时介入、短期成功导向。","rel_trigger":"B首位触发T4；B靠前且D靠后也触发T4。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"中班幼儿的问题解决依赖具体材料和反复操作；教育价值在于持续探究经验，而不只是一次引水成功。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"幼儿园探究游戏中的教师支持应鼓励合作、坚持和再尝试，避免把科学探索变成教师演示或结果竞赛。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"低估兴趣重建和材料支架","signal":"D排末位或明显靠后；B/A/C均压过D。","why":"","problem":"","check":"为什么不优先通过材料和情境重新激发探索。","missing":[],"trigger":"T1","script":["Q1","Q-stop"]},{"code":"P2","name":"示范过度或示范边界不清","signal":"A首位且教师解释为直接教正确做法。","why":"","problem":"","check":"示范多长、示范什么、幼儿是否再自己试。","missing":[],"trigger":"T2","script":["Q1","Q-stop"]},{"code":"P3","name":"抽象讨论优先","signal":"C首位，且缺少具体材料或观察依据。","why":"","problem":"","check":"讨论问题如何具体化，是否能回到材料尝试。","missing":[],"trigger":"T3","script":["Q1","Q-stop"]},{"code":"P4","name":"即时共调和短期成功导向","signal":"B首位或B明显靠前，尤其D靠后。","why":"","problem":"","check":"教师是怎样“一起尝试”的，是否由儿童提出方案。","missing":[],"trigger":"T4","script":["Q1","Q-stop"]},{"code":"P5","name":"完全放任材料投放","signal":"D首位但访谈中只说“再给材料让他们玩”。","why":"","problem":"","check":"投放材料后观察什么、何时进一步支持。","missing":[],"trigger":"T5","script":["Q1","Q-stop"]},{"code":"P6","name":"忽视文化与安全边界","signal":"只强调自由探索，不考虑水量、场地、材料秩序和同伴轮流。","why":"","problem":"","check":"如何让儿童在规则中继续探索。","missing":[],"trigger":"T6","script":["Q1","Q-stop"]},{"code":"P7","name":"把成功结果等同于学习质量","signal":"教师多次强调“把水引过去就行”。","why":"","problem":"","check":"幼儿在过程中获得了什么可迁移经验。","missing":[],"trigger":"T7","script":["Q1","Q-stop"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"B 排首位或进入前二","target":"B看似贴近问题，但“加入并一起调整”容易变成教师即时修正和局部调对，弱化儿童通过材料、观察和试误形成经验；第8题赋分中B首位平均最低，B末位平均最高。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"D抓住了题干中“兴趣减弱、有人离开”的关键信号。通过材料扩展和环境支架重建探索条件，符合中班幼儿通过操作经验学习的特点，也有利于长期探究兴趣。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_A","prio":3,"result_cond":"A 排末位","target":"A能够把水流方向、坡度和入口关系具体化。对中班幼儿而言，短时、可观察、可复做的示范比抽象讨论更发展适宜。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(D/A)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"中班幼儿的问题解决依赖具体材料和反复操作；教育价值在于持续探究经验，而不只是一次引水成功。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"幼儿园探究游戏中的教师支持应鼓励合作、坚持和再尝试，避免把科学探索变成教师演示或结果竞赛。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能通过增加可操作材料、调整支点、提供可观察线索或短时示范，帮助幼儿重新尝试，而不把教师成功替代儿童探索。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"教师马上加入并带着幼儿调对竹片，短期完成任务但削弱儿童试误、探索和迁移经验。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q9":{"kb_id":"GSYG_09","core_orientation":"考察教师能否理解幼儿对共同游戏规则的实际体验水平，通过短时体验、反思提问和规则协商帮助幼儿理解共同规则的意义。","empirical_note":"第9题赋分中最高分排序为DCBA，D是核心高分锚点：先让幼儿体验各走各的，再通过体验反思理解共同规则；C有规则共建价值，但更适合D之后推进。","paths":[{"option":"D","type":"D首位","suggest_pos":"","reason":"","not_denying":"","evidence":[],"rel_bias":"","rel_trigger":""},{"option":"C","type":"C靠前但不孤立首位","suggest_pos":"","reason":"","not_denying":"","evidence":[],"rel_bias":"","rel_trigger":""},{"option":"A","type":"A靠前","suggest_pos":"","reason":"","not_denying":"","evidence":[],"rel_bias":"","rel_trigger":""},{"option":"B","type":"B靠前","suggest_pos":"","reason":"","not_denying":"","evidence":[],"rel_bias":"","rel_trigger":""},{"option":"D","type":"D末位","suggest_pos":"","reason":"","not_denying":"","evidence":[],"rel_bias":"","rel_trigger":""}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"大班儿童可以通过体验比较和协商形成规则意识；支持目标不是立即统一玩法，而是促进规则意义的内化。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"共同规则体现集体游戏文化，但规则共建应让儿童参与理解和协商，而不是只接受教师规定。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"","signal":"","why":"","problem":"您为什么没有优先考虑让孩子先体验一下各走各的效果？","check":"您为什么没有优先考虑让孩子先体验一下各走各的效果？","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P2","name":"","signal":"","why":"","problem":"在孩子还没意识到各走各的问题时，您怎样让商量规则变成孩子自己的需要？","check":"在孩子还没意识到各走各的问题时，您怎样让商量规则变成孩子自己的需要？","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P3","name":"","signal":"","why":"","problem":"讲解规则之后，您会怎样让孩子自己重新判断该怎么走？","check":"讲解规则之后，您会怎样让孩子自己重新判断该怎么走？","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P4","name":"","signal":"","why":"","problem":"您会观察多久？出现什么情况会提前介入？","check":"您会观察多久？出现什么情况会提前介入？","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P5","name":"","signal":"","why":"","problem":"您觉得孩子亲自体验各走各的游戏效果，对理解规则有没有帮助？","check":"您觉得孩子亲自体验各走各的游戏效果，对理解规则有没有帮助？","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P6","name":"","signal":"","why":"","problem":"除了让他们不争执，您还希望他们从这次游戏中学到什么？","check":"除了让他们不争执，您还希望他们从这次游戏中学到什么？","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P7","name":"","signal":"","why":"","problem":"如果孩子继续各走各的，您会不会认为这仍然是飞行棋共同游戏？为什么？","check":"如果孩子继续各走各的，您会不会认为这仍然是飞行棋共同游戏？为什么？","missing":[],"trigger":"","script":["Q1","Q-stop"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"C 排首位或进入前二","target":"确认教师是否高估了风险路径 C，能否看见儿童游戏兴趣与适宜支持。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"确认教师是否低估了高价值路径 D 的专业价值。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_B","prio":3,"result_cond":"B 排末位","target":"确认教师是否低估了高价值路径 B 的专业价值。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(D/B)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"大班儿童可以通过体验比较和协商形成规则意识；支持目标不是立即统一玩法，而是促进规则意义的内化。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"共同规则体现集体游戏文化，但规则共建应让儿童参与理解和协商，而不是只接受教师规定。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能让儿童短时体验“各走各的”带来的问题，再询问体验、提示共同规则作用，并支持其商量一个骰子的轮流规则。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"直接讲解或拿走骰子建立规则，儿童可能知道规则但未真正理解规则为什么需要。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]},"Q10":{"kb_id":"GSYG_10","core_orientation":"考察教师能否在集体游戏秩序和安全风险中作出适时回应，并引导幼儿参与规则形成，逐步建立安全、公平、可持续的共同游戏文化。","empirical_note":"第10题赋分中B是最强高分锚点，即请幼儿说问题并共同设置规则；D具有照片/视频回放促进反思的长期价值；A是必要但偏即时的安全组织；C增加材料和言语引导风险较高。","paths":[{"option":"B","type":"实证高分锚点：规则共建路径","suggest_pos":"优先/高价值锚点","reason":"B直接指向大班幼儿共同发现问题和设置规则，是本题赋分中的最强高分路径；最高分排序为BDAC，B首位平均得分最高。","not_denying":"不是说教师完全不需要现场组织；B之后仍可结合A的分组分区和D的回放反思。","evidence":["E1","E2","E3","E5"],"rel_bias":"B靠后或B末位是重要风险。","rel_trigger":"B靠后触发T4；B首位可触发T5高水平确认。"},{"option":"D","type":"体验反思锚点：回放协商路径","suggest_pos":"高价值证据点","reason":"D体现对大班幼儿经验反思能力和长期规则形成的重视，能够避免过度成人控制。","not_denying":"不是说可以无条件放任现场安全风险；D需要与风险判断和必要即时组织结合。","evidence":["E4","E6","E7"],"rel_bias":"D首位需核查是否忽视现场安全；D靠后需核查是否忽视长期反思。","rel_trigger":"D首触发T2；D靠前可触发T6完整链条确认。"},{"option":"A","type":"即时组织路径","suggest_pos":"必要但不宜单一","reason":"A能直接处理拥挤和碰撞风险，有现场安全价值；但若单独排首位且缺少儿童讨论，容易变成成人分配式管理。","not_denying":"不是否定即时安全处理；安全风险较高时，A可能是必要补充。","evidence":["E2","E5","E1","E4"],"rel_bias":"A首位且B/D靠后提示即时管控优先。","rel_trigger":"A首触发T1。"},{"option":"C","type":"材料补充与言语引导路径","suggest_pos":"较低/不宜靠前","reason":"C有材料支持意识，但容易把问题归因为材料不足或教师提醒不足；若不先形成空间、人数、轮换规则，更多材料可能加剧混乱。C末位平均得分最高，说明C更适合放在靠后位置。","not_denying":"不是说不能补充材料；材料应服务于规则共建和空间组织，而不是替代规则协商。","evidence":["E5","E1","E3"],"rel_bias":"C首位或C靠前是主要风险。","rel_trigger":"C首或C靠前触发T3。"}],"evidence_points":[{"code":"E1","name":"指标定位证据：对游戏行为的分析与回应","high":"回答能明确体现“对游戏行为的分析与回应”的专业要求，并与本题情境相匹配。","low":"回答无法回到既定指标，只停留在一般性管理或经验判断。","from":"高分路径靠前通常需确认；风险路径靠前需追问。","triggers":["T1","T2"],"anchor":"高/中高核心分界。"},{"code":"E2","name":"儿童游戏意义或行为信息识别","high":"能说明儿童行为背后的兴趣、需要、经验、角色、规则、材料或学习线索。","low":"只看到表面行为，如乱、慢、不守规则、不会做、偏离目标。","from":"与主三级和次三级指标共同判断。","triggers":["T1","T3"],"anchor":"高水平必要证据。"},{"code":"E3","name":"观察与分析判断","high":"能说明自己如何观察、依据什么判断儿童真实需要或游戏状态。","low":"凭第一印象或成人目标直接下判断。","from":"过程数据中高修正/首位摇摆题尤需核查。","triggers":["T2","T3"],"anchor":"中高水平分界。"},{"code":"E4","name":"介入时机把握","high":"能说明什么时候介入、为什么此时介入或暂缓介入。","low":"要么立即控制，要么无边界旁观。","from":"与“介入时机的把握”相关题重点核查。","triggers":["T3","T4"],"anchor":"高/中水平分界。"},{"code":"E5","name":"介入方式适宜有效","high":"能提出具体、低控制、可操作的支架方式，如提问、材料、环境、同伴、角色或规则共建。","low":"只说“引导一下”“提醒一下”，缺少具体做法。","from":"与高分路径的具体策略一致时为强证据。","triggers":["T4","T5"],"anchor":"高水平加分证据。"},{"code":"E6","name":"年龄适宜性与长期效果","high":"大班儿童能够参与规则制定和反思，教师支持不只追求现场安静，更要促进共同游戏文化形成。","low":"使用过抽象、过控制或过结果化策略，忽视儿童年龄特点和游戏价值的循序性。","from":"若教师选择即时见效路径，需重点追问。","triggers":["T5","T6"],"anchor":"中高以上必要证据。"},{"code":"E7","name":"文化适宜性与教师角色","high":"幼儿园集体游戏需要安全、公平和秩序，但文化适宜的规则不是教师单向管理，而是儿童参与理解和共同维护。","low":"把规则、安全、共同生活或材料管理处理成单向服从，或完全放任个体兴趣。","from":"集体游戏、公共材料、规则安全类题目尤其重要。","triggers":["T6","T7"],"anchor":"综合判断证据。"}],"biases":[{"code":"P1","name":"即时管控优先","signal":"A首位且B/D靠后。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P2","name":"延后反思可能忽视现场安全","signal":"D首位且A/B靠后。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P3","name":"材料补充替代规则共建","signal":"C首位或C靠前，尤其C在B/D之前。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P4","name":"低估儿童参与规则制定","signal":"B末位或明显靠后。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P5","name":"忽视长期反思与规则内化","signal":"D末位且A/C靠前。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P6","name":"只讨论不落实","signal":"B首但A/C/D后续逻辑不清。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]},{"code":"P7","name":"放任式理解自主","signal":"D靠前且回答中强调“不干预”，但不能说明安全边界。","why":"","problem":"","check":"","missing":[],"trigger":"","script":["Q1","Q-stop"]}],"triggers":[{"code":"T_risk","prio":3,"result_cond":"A 排首位或进入前二","target":"A能直接处理拥挤和碰撞风险，有现场安全价值；但若单独排首位且缺少儿童讨论，容易变成成人分配式管理。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_B","prio":3,"result_cond":"B 排末位","target":"B直接指向大班幼儿共同发现问题和设置规则，是本题赋分中的最强高分路径；最高分排序为BDAC，B首位平均得分最高。","scripts":["Q1","Q2","Q3"]},{"code":"T_lowvalue_D","prio":3,"result_cond":"D 排末位","target":"D体现对大班幼儿经验反思能力和长期规则形成的重视，能够避免过度成人控制。","scripts":["Q1","Q2","Q3"]},{"code":"T_confirm","prio":1,"result_cond":"高价值选项(B/D)占据前二","target":"高水平确认：教师能否讲清判断依据、现场语言与后续支持策略。","scripts":["Q1","Q5","Q6"]},{"code":"T_process","prio":2,"result_cond":"过程振荡/多次修改（由过程标签触发）","target":"研究教师在多条专业路径之间如何权衡（结合过程标签追问）。","scripts":["Q1","Q3"]}],"scripts":{"Q1":{"stage":"回放理解","applies":"所有规则","q":"刚才这个情境中，您最先注意到的是什么？您觉得孩子的行为背后可能表达了什么兴趣、需要或游戏经验？","goal":"确认教师是否能看见儿童行为背后的游戏意义和指标相关信息。","E":["E2","E3"],"next":"若回答空泛，转Q2；若能说明具体行为意义，转Q3。"},"Q2":{"stage":"指标定位追问","applies":"排序或得分与高分路径不一致","q":"这个情境主要涉及“对游戏行为的分析与回应”。从这个角度看，您为什么会优先采用您选择的做法？","goal":"让教师解释其判断依据是否符合主三级指标要求。","E":["E1","E3"],"next":"若只讲管理目标，追问Q4；若能解释儿童经验，追问Q5。"},"Q3":{"stage":"判断依据追问","applies":"过程标签显示犹豫/修改","q":"您在这个题目中如果有过犹豫，通常会在什么地方犹豫？是儿童兴趣、规则安全、材料条件、还是介入方式之间的权衡？","goal":"解释过程数据背后的判断机制。","E":["E3","E4"],"next":"根据缺失证据选择Q4或Q5。"},"Q4":{"stage":"现场策略追问","applies":"策略表达不够具体","q":"如果在真实班级里遇到类似情况，您会对孩子说哪一句话，或者具体做哪一个动作来支持他们？","goal":"检验教师是否能把理念转化为具体回应。","E":["E5"],"next":"若仍空泛，记录具体策略不足；若具体，进入Q5。"},"Q5":{"stage":"发展适宜追问","applies":"年龄适宜性/长期效果需确认","q":"大班儿童能够参与规则制定和反思，教师支持不只追求现场安静，更要促进共同游戏文化形成。 结合这一点，您觉得处理这个情境时，哪些做法不一定需要马上见效？","goal":"检验教师是否理解年龄适宜性和长期教育效果。","E":["E6"],"next":"进入Q6。"},"Q6":{"stage":"文化适宜追问","applies":"涉及规则/公共空间/文化语境","q":"幼儿园集体游戏需要安全、公平和秩序，但文化适宜的规则不是教师单向管理，而是儿童参与理解和共同维护。 您会怎样既尊重孩子，又维护班级共同生活和游戏质量？","goal":"检验教师是否能进行文化适宜的平衡。","E":["E7"],"next":"进入Q7或收束。"},"Q7":{"stage":"迁移支持","applies":"需要迁移判断","q":"如果下周又出现类似情况，您会怎样调整环境、材料、规则或自己的介入方式，让孩子的游戏经验继续发展？","goal":"判断教师能否从一次处理转向持续支持。","E":["E5","E6","E7"],"next":"完成本题评分，进入下一题。"},"Q-stop":{"stage":"停止规则","applies":"证据充分","q":"您刚才已经说明了对孩子行为的理解、介入依据和后续支持方式，我们进入下一个情境。","goal":"避免机械追问。","E":[],"next":"进入下一题。"}},"anchors":[{"level":"高","core":"能够在既定指标体系下完整解释本题，并生成具体、适宜、可持续的支持策略。","performance":"能先保障现场安全，再让幼儿说出问题、共同制定分区、轮换、等待和使用材料的规则，并用回放促进长期内化。 同时能说明年龄适宜性和文化适宜性。","required":["E1","E2","E3","E4","E5","E6","E7"],"weak":[],"typical":"能说出具体观察依据、现场语言、材料/环境/规则支持和后续延展。","lack":"无核心缺失。","coding":"编码为高水平；若证据来自具体案例和现场话术，置信度高。","support":"高水平巩固型。"},{"level":"中高","core":"能够理解主要指标要求，并提出基本适宜的回应，但个别环节不够充分。","performance":"能说明儿童行为意义和基本介入思路，但长期支持、环境调整或文化平衡略显不足。","required":["E1","E2","E4","E5"],"weak":["E6","E7"],"typical":"回答有具体做法，但后续延展或规则共建较简略。","lack":"容易停留在一次性处理。","coding":"编码为中高；报告中写作“基础较好，仍可深化”。","support":"策略延展型/长期效果深化型。"},{"level":"中","core":"能说出一般原则，但指标解释和具体策略不够稳定。","performance":"常说“观察一下、引导一下、提醒一下”，但缺少证据化判断和具体支架。","required":["E2","E5"],"weak":["E3","E4","E6"],"typical":"能表达尊重儿童或注意规则，但不清楚怎样做。","lack":"专业语言空泛，难以迁移到现场。","coding":"编码为中等；需指出具体待提升指标。","support":"具体回应语言训练型/观察分析补强型。"},{"level":"偏低","core":"主要以成人目标、即时管理或表层行为解释本题。","performance":"把秩序问题简化为多给几根跳绳或教师不断提醒，未触及空间规则、公平等待和儿童参与规则形成。","required":[],"weak":["E1","E2","E4","E5"],"typical":"强调“不可以、要完成、要守规则、老师示范一下”等。","lack":"忽视儿童游戏框架、年龄特点或长期游戏价值。","coding":"编码为偏低；若追问后仍不能调整，置信度提高。","support":"主三级指标补强型/文化适宜性训练型。"},{"level":"证据不足","core":"回答过短、空泛或偏题，无法判断。","performance":"只说“我会引导”“要尊重孩子”“注意安全”，没有具体判断和做法。","required":[],"weak":[],"typical":"缺少具体语言、时机、材料、环境或规则安排。","lack":"无法支持可靠能力判断。","coding":"继续追问一次具体现场做法；仍不足则记录证据不足。","support":"具体回应语言训练型。"}],"suggestions":[{"type":"主三级指标补强型：对游戏行为的分析与回应","when":"该题得分偏低，或访谈显示无法围绕“对游戏行为的分析与回应”解释判断。","goal":"准确理解本题所属三级指标，形成稳定的专业判断依据。","activities":"围绕本题重写“我为什么这样判断”和“我现场如何回应”两段话。","materials":"本题情境案例、题目知识库高低水平锚点。","expect":"从经验化判断转向指标化、证据化判断。","follow":"教师能否用规范指标语言解释自己的做法。"},{"type":"儿童游戏意义识别补强型","when":"访谈中只看到表面行为或管理问题。","goal":"提升对儿童兴趣、需要、角色、材料、规则或探究线索的识别能力。","activities":"观看3个同类游戏片段，练习写“孩子在玩什么、为什么这样玩”。","materials":"游戏观察记录表。","expect":"从“看见问题”转向“看懂游戏”。","follow":"教师是否能先描述儿童经验，再提出支持。"},{"type":"观察分析补强型","when":"过程数据复杂或访谈中判断依据不清。","goal":"提升观察目的、观察角度和行为信息分析能力。","activities":"使用“行为—可能原因—证据—支持方式”四列表分析本题。","materials":"过程性数据回放、同伴教研案例。","expect":"从凭感觉介入转向有依据介入。","follow":"教师能否说明介入前观察到的证据。"},{"type":"适宜介入与支架训练型","when":"回答停留在提醒、讲解、示范、制止或空泛引导。","goal":"学习低控制、可操作、可退出的支持方式。","activities":"练习三类现场回应：提问支架、材料支架、环境/规则支架。","materials":"话术卡、材料调整案例。","expect":"从“老师解决”转向“支持儿童继续游戏”。","follow":"教师能否提出具体话术和支架步骤。"},{"type":"年龄适宜性与长期效果深化型","when":"回答追求马上合规、马上成功或马上纠正。","goal":"理解游戏价值的循序性和儿童年龄特点。","activities":"比较“即时管控版”和“长期支持版”两个处理方案。","materials":"小/中/大班游戏支持案例。","expect":"从立竿见影转向持续经验积累。","follow":"教师是否能提出后续观察、分享或环境延展。"},{"type":"文化适宜性协商型","when":"涉及规则、安全、公共材料或共同生活时，教师倾向单向管理或完全放任。","goal":"在儿童主体性与集体规则之间建立平衡。","activities":"设计一次儿童参与的规则讨论或材料使用约定。","materials":"规则共建、照片/视频回放案例。","expect":"从教师规定转向儿童理解并共同维护。","follow":"儿童是否能说出规则为什么需要。"},{"type":"高水平巩固型","when":"测验、过程和访谈证据均较好。","goal":"把已有经验提炼为园本教研案例。","activities":"整理本题优秀回应脚本和一次实际游戏支持案例。","materials":"优秀教师案例库。","expect":"从个体经验转化为可分享的专业资源。","follow":"能否为同伴提供可复制策略。"}]}};
